-- STG_MINDLINK_INTERNACOES: 3305 registros

COMMIT;

-- STG_MINDLINK_COMORBIDADES: 1868 registros

COMMIT;

-- STG_MINDLINK_CAPACIDADE: 6637 registros

COMMIT;

-- Dimensões e fatos derivados integralmente das tabelas de importação.
SELECT COMPETENCIA,
       TRUNC(COMPETENCIA / 100),
       MOD(COMPETENCIA, 100),
       CEIL(MOD(COMPETENCIA, 100) / 3),
       TO_DATE(TO_CHAR(COMPETENCIA) || '01', 'YYYYMMDD')
FROM (
    SELECT COMPETENCIA FROM STG_MINDLINK_INTERNACOES
    UNION
    SELECT COMPETENCIA FROM STG_MINDLINK_CAPACIDADE
);

SELECT CODIGO_IBGE,
       MAX(MUNICIPIO_ATENDIMENTO) KEEP (DENSE_RANK LAST ORDER BY COMPETENCIA),
       'SP'
FROM (
    SELECT COMPETENCIA, CODIGO_IBGE, MUNICIPIO_ATENDIMENTO
    FROM STG_MINDLINK_INTERNACOES
    UNION ALL
    SELECT COMPETENCIA, CODIGO_IBGE, MUNICIPIO_ATENDIMENTO
    FROM STG_MINDLINK_CAPACIDADE
)
GROUP BY CODIGO_IBGE;

SELECT CNES,
       MAX(NOME_ESTABELECIMENTO) KEEP (DENSE_RANK LAST ORDER BY COMPETENCIA),
       MAX(CODIGO_IBGE) KEEP (DENSE_RANK LAST ORDER BY COMPETENCIA),
       MAX(DS_TIPO_UNIDADE) KEEP (DENSE_RANK LAST ORDER BY COMPETENCIA),
       MAX(TP_GESTAO) KEEP (DENSE_RANK LAST ORDER BY COMPETENCIA)
FROM (
    SELECT COMPETENCIA, CNES, NOME_ESTABELECIMENTO, CODIGO_IBGE,
           DS_TIPO_UNIDADE, TP_GESTAO
    FROM STG_MINDLINK_CAPACIDADE
    UNION ALL
    SELECT COMPETENCIA, CNES, NOME_ESTABELECIMENTO, CODIGO_IBGE,
           CAST(NULL AS VARCHAR2(120)) AS DS_TIPO_UNIDADE,
           CAST(NULL AS VARCHAR2(10)) AS TP_GESTAO
    FROM STG_MINDLINK_INTERNACOES
)
GROUP BY CNES;

SELECT CODIGO_CID,
       MAX(DESCRICAO_CID),
       CASE
           WHEN SUBSTR(CODIGO_CID, 1, 3) IN ('F00','F01','F02','F03','G30')
           THEN 'DEMENCIA_PRINCIPAL'
           ELSE 'DIAGNOSTICO_SECUNDARIO'
       END
FROM (
    SELECT CID_PRINCIPAL AS CODIGO_CID,
           DESCRICAO_CID_PRINCIPAL AS DESCRICAO_CID
    FROM STG_MINDLINK_INTERNACOES
    UNION ALL
    SELECT CID_SECUNDARIO,
           DESCRICAO_CID_SECUNDARIO
    FROM STG_MINDLINK_COMORBIDADES
)
GROUP BY CODIGO_CID;


     QTD_INTERNACOES, DIAS_PERMANENCIA, VALOR_TOTAL, QTD_OBITOS)
SELECT COMPETENCIA, CODIGO_IBGE, CNES, CID_PRINCIPAL, FAIXA_ETARIA, SEXO_DESC,
       QTD_INTERNACOES, DIAS_PERMANENCIA, VALOR_TOTAL, QTD_OBITOS
FROM STG_MINDLINK_INTERNACOES;

     QTD_INTERNACOES_COM_COMORBIDADE)
SELECT COMPETENCIA, CODIGO_IBGE, CNES, CID_PRINCIPAL, CID_SECUNDARIO,
       QTD_INTERNACOES_COM_COMORBIDADE
FROM STG_MINDLINK_COMORBIDADES;

     UTI_TOTAL_EXIST, UTI_TOTAL_SUS)
SELECT COMPETENCIA, CODIGO_IBGE, CNES, LEITOS_EXISTENTES, LEITOS_SUS,
       UTI_TOTAL_EXIST, UTI_TOTAL_SUS
FROM STG_MINDLINK_CAPACIDADE;

COMMIT;
